        sourceType = "Pet Battles",
        stepCount = 4,
        acquisition = "Difficulty: Medium - Unlock eligible tamer dailies and repeatedly open their bags, or buy a cage.\n\n1. For a direct collection purchase, search Battle Pets on the Auction House for Porcupette. To earn it yourself, begin the pet-tamer story with Audrey Burnhep in Stormwind (Alliance) or Varzok in Orgrimmar (Horde). The live quest route shows the next unfinished introduction.\n\n2. Unlock your faction's first grand-master daily: Lydia Accoste near Karazhan for Alliance, or Stone Cold Trixxy in Winterspring for Horde. Complete the one-time tamer progression before expecting the daily bag reward.\n\n3. Defeat the unlocked grand master with an appropriate healthy team, turn in the daily quest and open its Sack of Pet Supplies. Later continent grand masters and the Pandaria tamers offer additional eligible bags once their introductions are complete.\n\n4. Learn Porcupette if the item appears. If not, return after the daily reset or use another unlocked bag-awarding tamer. The drop chance is low; repeatedly defeating a tamer without a new quest reward does not create more bags.",
