        name = "Terrible Turnip",
        sourceType = "Farming",
        stepCount = 4,
        acquisition = "Difficulty: Medium - Random seed discovery and daily crop growth; buying a pet cage is much faster.\n\n1. Visit Farmer Yoon at Sunsong Ranch, Valley of the Four Winds 52.0,48.1. Complete A Helping Hand and the Learn and Grow lessons until you can plant, tend and harvest your own crops. The quest route resumes the first unfinished lesson on this character.\n\n2. Buy seeds from Merchant Greenfield at Halfhill, till your available plots, plant crops and remove their problems: water parched plants, defeat pests and weeds, and handle the prompted crop interactions. Return after the daily growth reset to harvest ripe plants.\n\n3. Loot Ominous Seed (item 85219) if a harvest yields it. It can come from any crop and needs no minimum Tillers reputation. More unlocked plots give more harvests, but no crop variety guarantees the seed.\n\n4. Plant the Ominous Seed in a tilled farm plot, tend it if needed, and return when the crop matures. Harvest Terrible Turnip and use the pet item. Alternatively buy a caged turnip and bypass the farm and random seed.",
