        acquisition = "Difficulty: Medium - Earn Honored through fishing dailies or reputation tokens, then buy the pet.\n\n1. Go to Anglers Wharf, Krasarang Wilds, and find Nat Pagle at 68.4,43.4. Check your reputation with The Anglers; Nat's friendship status is not the gate.\n\n2. Complete the available Anglers fishing dailies around the wharf, following their named catches or quest interactions. Alternatively use current Anglers reputation commendations when available from Pandaria Timewalking; wait for the event if choosing that method.\n\n3. At Honored return to Nat Pagle, buy Tiny Goldfish for 250 gold before discounts and use the item. A bought cage from another player is an alternative if you want the species without the reputation.",
