        petNPCID = 62954,
        name = "Stormwind Rat",
        sourceType = "Pet Battles",
        stepCount = 4,
        acquisition = "Difficulty: Easy - An ordinary wild capture once you have a team strong enough for this area's pets.\n\n1. Open the Pet Journal and prepare a healthy team. Bring a pet near the target's level or Terrible Turnip with Weakening Blow so a critical hit does not kill the pet you want to trap.\n\n2. Travel to Stormwind's Old Town / SI:7 courtyard (78.2,63.4). Search the lanes and courtyard for rats with a green paw. If city phasing hides them, use the gnoll camps near Hogger in Elwynn Forest instead. A Horde collector can catch it on an Alliance alt; the journal is account-wide.\n\n3. Start a pet battle and inspect all enemy slots for Stormwind Rat. Check the species name, not just its model. If it appears as a backline pet, defeat the enemies ahead of it before lowering its health.\n\n4. Lower Stormwind Rat below 35% health, then use Trap until the capture succeeds. Finish the rest of the enemy team and win the battle to keep it. Heal before the next attempt if necessary; only one enemy can be captured per battle.",
