        petNPCID = 63064,
        name = "Bandicoon Kit",
        sourceType = "Pet Battles",
        stepCount = 4,
        acquisition = "Difficulty: Easy - An ordinary wild capture once you have a team strong enough for this area's pets.\n\n1. Open the Pet Journal and prepare a healthy team. Bring a pet near the target's level or Terrible Turnip with Weakening Blow so a critical hit does not kill the pet you want to trap.\n\n2. Travel to Stoneplow surroundings, Valley of the Four Winds (19.0,50.0). Look for small kits following an adult Bandicoon, or battle ordinary Bandicoons and inspect their secondary pets. A family may share its initial battle lineup, so move to another family if every fight shows the same pets.\n\n3. Start a pet battle and inspect all enemy slots for Bandicoon Kit. Check the species name, not just its model. If it appears as a backline pet, defeat the enemies ahead of it before lowering its health.\n\n4. Lower Bandicoon Kit below 35% health, then use Trap until the capture succeeds. Finish the rest of the enemy team and win the battle to keep it. Heal before the next attempt if necessary; only one enemy can be captured per battle.",
        reviewedAt = "2026-11-13",
        wowheadUrl = "https://www.wowhead.com/npc=63064",
        references = { "https://www.wowhead.com/npc=63064" },
