        stepCount = 4,
        acquisition = "Difficulty: Easy - An ordinary wild capture once you have a team strong enough for this area's pets.\n\n1. Open the Pet Journal and prepare a healthy team. Bring a pet near the target's level or Terrible Turnip with Weakening Blow so a critical hit does not kill the pet you want to trap.\n\n2. Travel to Gao-Ran Battlefront, Townlong Steppes (75.0,83.0). Check the camp and surrounding grass. Yakrats also accompany many other Townlong species, so battle nearby mongoose families while waiting for visible rats to respawn.\n\n3. Start a pet battle and inspect all enemy slots for Yakrat. Check the species name, not just its model. If it appears as a backline pet, defeat the enemies ahead of it before lowering its health.\n\n4. Lower Yakrat below 35% health, then use Trap until the capture succeeds. Finish the rest of the enemy team and win the battle to keep it. Heal before the next attempt if necessary; only one enemy can be captured per battle.",
