        acquisition = "Difficulty: Easy - An ordinary wild capture once you have a team strong enough for this area's pets.\n\n1. Open the Pet Journal and prepare a healthy team. Bring a pet near the target's level or Terrible Turnip with Weakening Blow so a critical hit does not kill the pet you want to trap.\n\n2. Travel to eastern Vale pools (69.0,44.8). Search the water's edge and inspect secondary pets in nearby Vale battles. Keep clear of hostile crocolisks while starting the battle. Use Zidormi's earlier Vale if assault phasing prevents a comfortable search.\n\n3. Start a pet battle and inspect all enemy slots for Yellow-Bellied Bullfrog. Check the species name, not just its model. If it appears as a backline pet, defeat the enemies ahead of it before lowering its health.\n\n4. Lower Yellow-Bellied Bullfrog below 35% health, then use Trap until the capture succeeds. Finish the rest of the enemy team and win the battle to keep it. Heal before the next attempt if necessary; only one enemy can be captured per battle.",
        reviewedAt = "2026-11-13",
        wowheadUrl = "https://www.wowhead.com/npc=63849",
        references = { "https://www.wowhead.com/npc=63849" },
    },
