    [792] = {
        category = "Vendor",
        source = "Battle Pet Training on a Pandaren character",
        itemId = 88148,
        description = "The Pandaren racial starter pet, learned through the capital pet trainer and shared by the account.",
        difficulty = "easy",
        difficultyReason = "A short racial-trainer interaction; a cage can bypass making a Pandaren.",
        requirements = "A Pandaren character for the trainer route, or a suitable bought cage",
        cost = "Trainer purchase/training fee or player-set cage price",
        tips = "A Pandaren of either faction can unlock the pet. You do not have to keep playing that character to use the account-wide companion, and do not need Order of the Cloud Serpent reputation.",
        waypoints = {
            {
                mapID = 84,
                x = 0.6940000000000001,
                y = 0.244,
                step = 2,
                label = "Audrey Burnhep - Pandaren Alliance racial pet",
            },
            { mapID = 85, x = 0.526, y = 0.593, step = 2, label = "Varzok - Pandaren Horde racial pet" },
        },
        commentIDs = { 1720542, 1787046 },
        petNPCID = 65314,
        name = "Jade Crane Chick",
        sourceType = "Vendor",
        stepCount = 4,
        acquisition = "Difficulty: Easy - A short racial-trainer interaction; a cage can bypass making a Pandaren.\n\n1. Use a Pandaren character. Finish the starting experience and faction choice if using the Wandering Isle introduction, then travel to that faction's capital with Battle Pet Training available.\n\n2. Speak to Audrey Burnhep in Stormwind at 69.4,24.4 (Alliance) or Varzok in Orgrimmar at 52.6,59.3 (Horde). Learn Battle Pet Training if needed and use the offered racial-pet training/purchase to obtain Jade Crane Chick.\n\n3. If your account already knows Battle Pet Training, inspect the trainer's pet dialogue rather than expecting to relearn the whole battle system. Check the Pet Journal for Jade Crane Chick afterward.\n\n4. Alternatively buy a caged Jade Crane Chick from another player. The account-wide species can then be used by your other races; a generic crane seen on Pandaria's beaches is not a wild capture of this starter pet.",
        reviewedAt = "2026-11-13",
        wowheadUrl = "https://www.wowhead.com/npc=65314",
        references = { "https://www.wowhead.com/npc=65314", "https://www.wowhead.com/item=88148" },
    },
    [802] = {
        category = "Black Market",
