        difficulty = "hard",
        difficultyReason = "Random auction availability and competitive gold bidding; the pet cannot be caged.",
        requirements = "Access to the current Black Market and enough gold to win the auction",
        cost = "Winning Black Market bid; no fixed price",
        tips = "Challenge Conquerors: Gold - Guild Edition no longer unlocks this pet on a guild vendor. Use the current Black Market listing for item 85513. An unclaimed container is a random loot gamble, not a guaranteed substitute.",
        waypoints = {
            {
                mapID = 2393,
                x = 0.518,
                y = 0.485,
