        references = {
            "https://www.wowhead.com/item=85513",
            "https://warcraft.wiki.gg/wiki/Thundering_Serpent_Hatchling",
            "https://www.icy-veins.com/wow/news/black-market-auction-house-location-in-midnight/",
            "https://www.wowhead.com/npc=65313",
            "https://www.wowhead.com/item=85513",
        },
        commentIDs = { 2025995, 3127722 },
        petNPCID = 65313,
        name = "Thundering Serpent Hatchling",
        sourceType = "Black Market",
        stepCount = 4,
        acquisition = "Difficulty: Hard - Random auction availability and competitive gold bidding; the pet cannot be caged.\n\n1. Visit a currently active Black Market auctioneer and inspect the day's stock. Look specifically for Thundering Serpent Hatchling, item 85513; neither the old guild vendors nor the Veiled Stair's retired auction site supplies this purchase.\n\n2. If the pet is not listed, check after later auction refreshes. Availability is random. A historical screenshot of a listing is not evidence that your realm has one today.\n\n3. If listed and you want it at that price, bid with a character able to use the market and monitor whether another bidder outbids you. You must win the completed auction to receive the item by mail.\n\n4. Retrieve the hatchling item from your mailbox and use it. This species cannot be caged, so ordinary Battle Pet auction listings cannot replace winning the Black Market item.",
        reviewedAt = "2026-11-13",
        wowheadUrl = "https://www.wowhead.com/npc=65313",
    },
    [817] = {
