        },
        commentIDs = { 1726871, 1726867, 1726869, 1745666 },
        petNPCID = 65323,
        name = "Wild Jade Hatchling",
        sourceType = "Pet Battles",
        stepCount = 4,
        acquisition = "Difficulty: Medium - Earn Exalted before the otherwise ordinary wild capture.\n\n1. Start Wild Things with Elder Anli at the Arboretum, Jade Forest 57.7,45.0. Follow the Windward Isle errands, choose an egg and bring it back for It's A... . The quest route skips lessons already finished by this character.\n\n2. Raise Order of the Cloud Serpent reputation to Exalted through available daily quests and Onyx Egg turn-ins. Search the Windward Isle pillars for eggs; at Revered buy and use San Redscale's Grand Commendation before earning more reputation. Current Timewalking commendations are another method when offered.\n\n3. Return to the Arboretum's pink-tree area around 53.6,45.2. Find a green-paw Wild Jade Hatchling directly. If the hatchlings cannot be challenged, check this character's reputation rather than assuming the pet is removed.\n\n4. Bring a healthy team, lower the named hatchling below 35% health and trap it. Finish its accompanying pets to retain the catch. Check backline slots for other Jade Forest species while collecting all three serpent colours.",
        reviewedAt = "2026-11-13",
        wowheadUrl = "https://www.wowhead.com/npc=65323",
        references = { "https://www.wowhead.com/npc=65323" },
    },
