    [820] = {
        category = "Achievements",
        source = "Pro Pet Crew - raise 75 pets to level 25",
        itemId = 88147,
        sourceAchievementId = 6582,
        description = "A pet-leveling milestone, distinct from owning seventy-five species or catching a wild cricket.",
        difficulty = "hard",
        difficultyReason = "Seventy-five qualifying pet level-ups to 25 require substantial training or leveling-stone resources.",
        requirements = "75 qualifying level-25 pets credited by Pro Pet Crew",
        cost = "No reward purchase; optional leveling-stone cost",
        tips = "Track Pro Pet Crew itself: buying a cage already at 25 is not the same action as raising a pet to 25. Modern leveling stones and tamer XP can help; use the achievement counter to confirm each chosen method's credit.",
        waypoints = {
            {
                mapID = 376,
                x = 0.62,
                y = 0.35,
                step = 3,
                label = "Pools of Purity - optional aquatic wild-battle leveling route",
            },
        },
        petNPCID = 64232,
        name = "Singing Cricket",
        sourceType = "Achievements",
        stepCount = 4,
        acquisition = "Difficulty: Hard - Seventy-five qualifying pet level-ups to 25 require substantial training or leveling-stone resources.\n\n1. Open Pro Pet Crew (achievement 6582) and track its count. Prepare a pair of strong level-25 combat pets and a lower-level pet that you want to train.\n\n2. Use unlocked pet-tamer dailies or repeatable wild battles to level the lower pet, swapping it safely into battle before your stronger pets finish. Heal between fights and avoid exposing a level-1 pet to dangerous opening attacks.\n\n3. For an accessible Pandaria wild route, battle aquatic pets around the Pools of Purity in Valley of the Four Winds. A strong Flying pet deals extra damage to aquatics; carry only a pet that can survive its participation. Leveling stones provide a faster alternative where available.\n\n4. Repeat with enough pets for 75 qualifying level-25 raises. When Pro Pet Crew completes, check the reward delivery / journal and learn Singing Cricket. The wild Marsh Fiddler's similar appearance does not award this achievement pet.",
        reviewedAt = "2026-11-13",
        wowheadUrl = "https://www.wowhead.com/npc=64232",
        references = { "https://www.wowhead.com/npc=64232", "https://www.wowhead.com/item=88147" },
    },
    [821] = {
        category = "Achievements",
        source = "Collect 250 different companion pets",
        itemId = 85578,
        sourceAchievementId = 7500,
        description = "An account-wide species-collection milestone. Duplicate copies do not increase the unique-pet count.",
        difficulty = "medium",
        difficultyReason = "A broad collection target; inexpensive vendors and ordinary captures make steady progress.",
        requirements = "250 different eligible pet species",
        cost = "Varies with collecting methods; no reward purchase",
        tips = "Check achievement 7500 for progress. Collecting three copies or multiple breeds of one species is still one species. Use the Auction House's uncollected filter to avoid buying duplicates.",
        waypoints = {
            {
                mapID = 125,
                x = 0.586,
                y = 0.396,
                step = 2,
                label = "Breanni - optional inexpensive species for the collection milestone",
            },
        },
        petNPCID = 63621,
        name = "Feral Vermling",
        sourceType = "Achievements",
        stepCount = 4,
        acquisition = "Difficulty: Medium - A broad collection target; inexpensive vendors and ordinary captures make steady progress.\n\n1. Open the achievement tracker for 250 unique companion pets and the Pet Journal's uncollected filter. Build the collection using Kalimdor / Eastern Kingdoms pet vendors; your character's level is not a count of collected species.\n\n2. Start with inexpensive vendor species: Breanni in Northrend Dalaran 58.6,39.6 and the racial pet vendors in your capitals. Learn each new species immediately. Compare your owned count before buying another colour that may be the same species.\n\n3. Use wild pet battles to collect missing species zone by zone. The newly listed Pandaria wild pets provide many additions without rare raid drops. For bought cages check that your account can learn their pet level.\n\n4. Continue until the achievement's unique count reaches 250. Claim/learn the Feral Vermling reward when delivered, checking the Pet Journal and mailbox. There is no separate reputation or quest turn-in after the milestone.",
        reviewedAt = "2026-11-13",
        wowheadUrl = "https://www.wowhead.com/npc=63621",
        references = { "https://www.wowhead.com/npc=63621", "https://www.wowhead.com/item=85578" },
    },
    [823] = {
