        difficulty = "easy",
        difficultyReason = "An ordinary wild capture once you have a team strong enough for this area's pets.",
        requirements = "Battle Pet Training, an unlocked trap, and pets suitable for the local battle level",
        cost = "No purchase; wild captures cannot be bought as cages",
        tips = "Track Pets on the minimap. A green paw identifies a battle pet. Catching any quality is enough to add the species; a battle-stone can improve quality later.",
        commentIDs = { 1736885, 6190077 },
        waypoints = {
            { mapID = 241, x = 0.456, y = 0.413, step = 2, label = "central Twilight Highlands - Highlands Skunk search area" },
        },
        petNPCID = 62907,
        name = "Highlands Skunk",
        sourceType = "Pet Battles",
        stepCount = 4,
        acquisition = "Difficulty: Easy - An ordinary wild capture once you have a team strong enough for this area's pets.\n\n1. Open the Pet Journal and prepare a healthy team. Bring a pet near the target's level or Terrible Turnip with Weakening Blow so a critical hit does not kill the pet you want to trap.\n\n2. Travel to central Twilight Highlands (45.6,41.3). Search the grassy ground and inspect the backline of local battles, including Twilight Whelplings near Grim Batol. The old journal label pointing to Arathi was wrong; use Twilight Highlands.\n\n3. Start a pet battle and inspect all enemy slots for Highlands Skunk. Check the species name, not just its model. If it appears as a backline pet, defeat the enemies ahead of it before lowering its health.\n\n4. Lower Highlands Skunk below 35% health, then use Trap until the capture succeeds. Finish the rest of the enemy team and win the battle to keep it. Heal before the next attempt if necessary; only one enemy can be captured per battle.",
        reviewedAt = "2026-11-13",
        wowheadUrl = "https://www.wowhead.com/npc=62907",
        references = { "https://www.wowhead.com/npc=62907" },
    },
    [834] = {
        category = "Rare Drops",
        source = "Karr the Darkener",
        itemId = 86564,
        description = "Obtain the teaching item from Karr the Darkener, or learn a caged Grinder bought from another player.",
        difficulty = "medium",
        difficultyReason = "The source is easy to defeat at a high level, but finding it and obtaining the random drop may take repeated attempts.",
        requirements = "Access to the source area and a character able to defeat the enemy",
        cost = "No vendor cost; optional player-set cage price",
        tips = "Use ordinary character combat and loot the enemy. The small companion's own NPC page can show where players summoned it; use the actual source's location instead.",
        commentIDs = { 1763747, 2097940 },
        waypoints = { { mapID = 422, x = 0.718, y = 0.376, step = 1, label = "Karr the Darkener - acquisition area" } },
        petNPCID = 64634,
        name = "Grinder",
        sourceType = "Rare Drops",
        stepCount = 4,
        acquisition = "Difficulty: Medium - The source is easy to defeat at a high level, but finding it and obtaining the random drop may take repeated attempts.\n\n1. Travel to 71.8,37.6. Go to the Terrace of Gurthan in the Dread Wastes and check Karr's camp. The Grinder companion's summoned location is not Karr's spawn. If he vanishes as you approach, finish the local quest phase or use another character.\n\n2. Find and defeat Karr the Darkener, then loot the corpse. If absent, search the surrounding route and return after a respawn. Another player's spawn timer is not a guaranteed appointment for your realm or phase.\n\n3. Look for Imbued Jade Fragment in the loot and use it to learn Grinder. If it does not drop, repeat the source. Reaching the marked location alone does not award a pet.\n\n4. Alternatively buy a caged Grinder in the Auction House's Battle Pets category. Check its required pet level; you need a sufficiently high-level pet already in your collection to learn a high-level cage.",
        reviewedAt = "2026-11-13",
        wowheadUrl = "https://www.wowhead.com/npc=64634",
        references = { "https://www.wowhead.com/npc=64634", "https://www.wowhead.com/item=86564" },
    },
    [835] = {
        category = "Achievements",
