        cost = "A few vendor teas",
        tips = "Any dungeon difficulty works. Hopocalypse Now! is a different achievement. Keep the tea buff active and search under stairs and behind barrels; the hoplings are clickable objects/NPCs, not enemies to kill or trap.",
