                step = 6,
                label = "Tasting Room - check beneath Yan-Zhu",
                mapName = "Stormstout Brewery - Tasting Room",
            },
            {
                mapID = 442,
                x = 0.324,
                y = 0.68,
                step = 6,
                label = "Tasting Room - outer ledge search",
                mapName = "Stormstout Brewery - Tasting Room",
            },
        },
        commentIDs = { 1719694, 1699178, 1734148, 1723239, 2559591, 3180235 },
        petNPCID = 64632,
        name = "Hopling",
        sourceType = "Achievements",
        stepCount = 7,
        acquisition = "Difficulty: Easy - A thorough dungeon search after clearing the enemies; no rare drop or daily grind.\n\n1. Enter Stormstout Brewery at Valley of the Four Winds 36.0,69.0 and buy several Ling-Ting's Favorite Teas from Auntie Stormstout just inside. Clear and search as you advance; do not postpone the early rooms until after Hoptallus, because killing him too quickly can leave the return door shut.\n\n2. Drink the tea to reveal Golden Hoplings for five minutes. Enable friendly nameplates, use /target Golden Hopling and mark the target with a raid icon. Click or use Interact With Target to collect it; targeting alone gives no credit. If renewing early, remove the existing buff first because another drink does not refresh an active buff.\n\n3. Sweep Trickling Passage and the Grain Cellar. Check behind barrels, along both walls, under stairs and on ledges. The interior map marks documented search clusters; not every hopling has one immutable spot. Shared party clicks count, so partners can search opposite sides.\n\n4. Search Mama's Pantry, Ook-Ook's Brewhall and the connecting stairs. A target macro can select a hopling on another floor: follow its marker and check above/below. Finish the early-room sweep before passing Hoptallus; let his door-close sequence and a combat cycle occur before killing him to preserve backtracking.\n\n5. Continue through the Great Wheel and Hoptallus area, checking corners, platform edges and stair landings. Refresh expired tea and use the map dropdown for the appropriate interior floor. If a target is awkward to click, use the Interact With Target key binding.\n\n6. Sweep the Tasting Room and Yan-Zhu's platform. Check directly under the defeated boss's head/body: several replies identify that as their missing thirtieth hopling. Recheck both sides and the entrance ledge until the total reaches thirty.\n\n7. When Ling-Ting's Herbal Journey completes, collect Auntie Stormstout's mailed Hopling and use it. The rewarded pet is white; the golden creatures were achievement search targets. Finish all thirty in the same instance before leaving or resetting.",
        reviewedAt = "2026-11-13",
        wowheadUrl = "https://www.wowhead.com/npc=64632",
        references = { "https://www.wowhead.com/npc=64632", "https://www.wowhead.com/item=86562" },
    },
    [836] = {
        category = "Rare Drops",
