        cost = "No vendor cost; optional player-set cage price",
        tips = "Use ordinary character combat and loot the enemy. The small companion's own NPC page can show where players summoned it; use the actual source's location instead.",
        commentIDs = { 1733953, 2868677 },
        waypoints = { { mapID = 422, x = 0.642, y = 0.586, step = 1, label = "Nalash Verdantis - acquisition area" } },
        petNPCID = 64633,
        name = "Aqua Strider",
        sourceType = "Rare Drops",
        stepCount = 4,
        acquisition = "Difficulty: Medium - The source is easy to defeat at a high level, but finding it and obtaining the random drop may take repeated attempts.\n\n1. Travel to 64.2,58.6. Search the Lake of Stars area in the Dread Wastes for Nalash. This is a named rare enemy, not the wild Eternal Strider or Dancing Water Skimmer.\n\n2. Find and defeat Nalash Verdantis, then loot the corpse. If absent, search the surrounding route and return after a respawn. Another player's spawn timer is not a guaranteed appointment for your realm or phase.\n\n3. Look for Hollow Reed in the loot and use it to learn Aqua Strider. If it does not drop, repeat the source. Reaching the marked location alone does not award a pet.\n\n4. Alternatively buy a caged Aqua Strider in the Auction House's Battle Pets category. Check its required pet level; you need a sufficiently high-level pet already in your collection to learn a high-level cage.",
        reviewedAt = "2026-11-13",
        wowheadUrl = "https://www.wowhead.com/npc=64633",
        references = { "https://www.wowhead.com/npc=64633", "https://www.wowhead.com/item=86563" },
    },
