        acquisition = "Difficulty: Easy - An ordinary wild capture once you have a team strong enough for this area's pets.\n\n1. Open the Pet Journal and prepare a healthy team. Bring a pet near the target's level or Terrible Turnip with Weakening Blow so a critical hit does not kill the pet you want to trap.\n\n2. Travel to the Quaking Fields, Deepholm (29.9,47.9). Look for the small green shale spiders. They are primary and secondary pets; the ordinary hostile shale spiders do not teach the companion. Capture any quality before considering a particular breed.\n\n3. Start a pet battle and inspect all enemy slots for Emerald Shale Hatchling. Check the species name, not just its model. If it appears as a backline pet, defeat the enemies ahead of it before lowering its health.\n\n4. Lower Emerald Shale Hatchling below 35% health, then use Trap until the capture succeeds. Finish the rest of the enemy team and win the battle to keep it. Heal before the next attempt if necessary; only one enemy can be captured per battle.",
