        acquisition = "Difficulty: Easy - An ordinary wild capture once you have a team strong enough for this area's pets.\n\n1. Open the Pet Journal and prepare a healthy team. Bring a pet near the target's level or Terrible Turnip with Weakening Blow so a critical hit does not kill the pet you want to trap.\n\n2. Travel to Therazane's Throne, Deepholm (57.0,13.2). Circle the rocks around the throne for densely packed purple hatchlings. An alternative is Maraudon's uninstanced Wicked Tunnels: take the left branch at Zaetar's Choice before entering either dungeon portal.\n\n3. Start a pet battle and inspect all enemy slots for Amethyst Shale Hatchling. Check the species name, not just its model. If it appears as a backline pet, defeat the enemies ahead of it before lowering its health.\n\n4. Lower Amethyst Shale Hatchling below 35% health, then use Trap until the capture succeeds. Finish the rest of the enemy team and win the battle to keep it. Heal before the next attempt if necessary; only one enemy can be captured per battle.",
