    [844] = {
        category = "Professions",
        source = "Pandaria Engineering - trainer recipe",
        itemId = 87526,
        description = "A crafted mechanical companion; Engineering is required to make it, not to learn a purchased pet.",
        difficulty = "easy",
        difficultyReason = "A trainer recipe with ordinary materials; a finished item or cage bypasses profession leveling.",
        requirements = "Pandaria Engineering 50 to craft; no profession needed for a suitable purchased pet",
        cost = "4 Ghost Iron Bars, 6 Trillium Bars, 2 Spirits of Harmony",
        tips = "Mechanical Pandaren Dragonling (pet item 87526) is different from Ghost Iron Dragonling (trinket 77530). The trinket's robot does not add this species to the Pet Journal.",
        waypoints = { { mapID = 376, x = 0.16, y = 0.83, step = 1, label = "Sally Fizzlefury - Pandaria Engineering" } },
        references = {
            "https://www.wowhead.com/spell=127135",
            "https://www.wowhead.com/item=87526",
            "https://www.wowhead.com/npc=64899",
            "https://www.wowhead.com/item=87526",
        },
        commentIDs = { 1787952 },
        petNPCID = 64899,
        name = "Mechanical Pandaren Dragonling",
        sourceType = "Professions",
        stepCount = 4,
        acquisition = "Difficulty: Easy - A trainer recipe with ordinary materials; a finished item or cage bypasses profession leveling.\n\n1. If you only want the pet, buy Mechanical Pandaren Dragonling or a suitable cage from another player and learn it. For self-crafting, visit Sally Fizzlefury at Nesingwary's Safari, Valley of the Four Winds 16.0,83.0, and train Pandaria Engineering.\n\n2. Raise Pandaria Engineering to 50 and learn Mechanical Pandaren Dragonling, crafting spell 127135, from the trainer. Search the Engineering recipe list for the full pet name rather than the Ghost Iron Dragonling trinket.\n\n3. Gather 4 Ghost Iron Bars, 6 Trillium Bars and 2 Spirits of Harmony. Make one pet item from the recipe, then use it from your bags to learn the companion.\n\n4. Check the Pet Journal for the species. A crafted item can teach an uncommon-quality pet despite its item colour; use a suitable battle-stone if you also want rare quality.",
        reviewedAt = "2026-11-13",
        wowheadUrl = "https://www.wowhead.com/npc=64899",
    },
    [845] = {
        category = "Professions",
        source = "Pandaria Jewelcrafting - discovered design",
        itemId = 82774,
        description = "The design is a random discovery, but a completed craft always produces the pet item.",
        difficulty = "medium",
        difficultyReason = "Self-crafting needs a random design; buying the finished pet skips discovery.",
        requirements = "Pandaria Jewelcrafting 75 and the learned design to craft; no profession needed for a purchased pet",
        cost = "3 Wild Jade and 3 Spirits of Harmony per pet",
        tips = "Design: Jade Owl is soulbound. The crafted pet item and caged companion are tradeable. Compare the cage's level and quality rather than assuming a blue teaching item gives a rare-quality pet.",
        waypoints = {
            {
                mapID = 371,
                x = 0.48100000000000004,
                y = 0.35,
                step = 1,
                label = "Mai the Jade Shaper - Pandaria Jewelcrafting",
            },
            { mapID = 390, x = 0.812, y = 0.29600000000000004, step = 2, label = "Zidormi - earlier Vale" },
            { mapID = 390, x = 0.22, y = 0.26, step = 3, label = "Guo-Lai Halls entrance - keyed caches inside" },
        },
        references = {
            "https://www.wowhead.com/item=90470",
            "https://www.wowhead.com/spell=131897",
            "https://www.wowhead.com/npc=61877",
            "https://www.wowhead.com/item=82774",
        },
        commentIDs = { 1757961, 1757960, 1879494 },
        petNPCID = 61877,
        name = "Jade Owl",
        sourceType = "Professions",
        stepCount = 4,
        acquisition = "Difficulty: Medium - Self-crafting needs a random design; buying the finished pet skips discovery.\n\n1. For the quickest route buy a finished Jade Owl item or a suitable cage. To make it yourself, train Pandaria Jewelcrafting with Mai the Jade Shaper in Greenstone Village, Jade Forest 48.1,35.0, and reach skill 75.\n\n2. Find Design: Jade Owl (item 90470). A continuing method is to obtain Ancient Guo-Lai Cache Keys from Vale mogu and open Ancient Guo-Lai Caches inside Guo-Lai Halls. Use Zidormi at 81.2,29.6 for the earlier Vale. Opening crafted Serpent's Hearts is another design-discovery chance if that recipe is known.\n\n3. For the cache route, enter Guo-Lai Halls around 22.0,26.0 and follow the passages to the treasure rooms. Spend a key on each Ancient Guo-Lai Cache. Keep trying until the actual design drops; reputation, keys and a completed pet are three different things.\n\n4. Learn the design, collect 3 Wild Jade and 3 Spirits of Harmony, then craft Jade Owl. Use the resulting item and check your Pet Journal. No Golden Lotus Exalted purchase or Order of the Cloud Serpent panther design is required for this pet.",
        reviewedAt = "2026-11-13",
        wowheadUrl = "https://www.wowhead.com/npc=61877",
    },
    [846] = {
        category = "Professions",
        source = "Pandaria Jewelcrafting - discovered design",
