        name = "Sapphire Cub",
        sourceType = "Professions",
        stepCount = 4,
        acquisition = "Difficulty: Medium - Self-crafting needs a random design; buying the finished pet skips discovery.\n\n1. For the quickest route buy a finished Sapphire Cub item or a suitable cage. To make it yourself, train Pandaria Jewelcrafting with Mai the Jade Shaper in Greenstone Village, Jade Forest 48.1,35.0, and reach skill 75.\n\n2. Find Design: Sapphire Cub (item 90471). A continuing method is to obtain Ancient Guo-Lai Cache Keys from Vale mogu and open Ancient Guo-Lai Caches inside Guo-Lai Halls. Use Zidormi at 81.2,29.6 for the earlier Vale. Opening crafted Serpent's Hearts is another design-discovery chance if that recipe is known.\n\n3. For the cache route, enter Guo-Lai Halls around 22.0,26.0 and follow the passages to the treasure rooms. Spend a key on each Ancient Guo-Lai Cache. Keep trying until the actual design drops; reputation, keys and a completed pet are three different things.\n\n4. Learn the design, collect 3 River's Heart and 3 Spirits of Harmony, then craft Sapphire Cub. Use the resulting item and check your Pet Journal. No Golden Lotus Exalted purchase or Order of the Cloud Serpent panther design is required for this pet.",
        reviewedAt = "2026-11-13",
