    [847] = {
        category = "Quest Rewards",
        source = "Alliance: Let Them Burn; Horde: What's in a Name Name?",
        itemId = 84105,
        description = "Both factions can earn Fishy through their own Jade Forest introduction and local alliance story.",
        difficulty = "medium",
        difficultyReason = "A substantial introductory quest chain; a caged pet bypasses the story.",
        requirements = "A character following the appropriate faction's Jade Forest story, or a suitable bought cage",
        cost = "No quest purchase",
        tips = "Follow the live character-specific quest route. It includes the prerequisites back to the original Pandaria departure, and skips completed quests. The final quest giver alone may have nothing to offer on a fresh character.",
        waypoints = {
            { mapID = 84, x = 0.789, y = 0.397, step = 1, label = "Rell Nightwind - The Mission, Alliance chain start" },
            { mapID = 371, x = 0.588, y = 0.8170000000000001, step = 3, label = "Instructor Sharpfin - Alliance Fishy reward" },
            { mapID = 85, x = 0.486, y = 0.708, step = 4, label = "Grommash Hold - Horde Pandaria departure" },
            {
                mapID = 371,
                x = 0.27899999999999997,
                y = 0.47100000000000003,
                step = 5,
                label = "Chief Kah Kah - Horde Fishy reward",
            },
        },
        petNPCID = 62829,
        name = "Fishy",
        sourceType = "Quest Rewards",
        stepCount = 5,
        acquisition = "Difficulty: Medium - A substantial introductory quest chain; a caged pet bypasses the story.\n\n1. Alliance: start The Mission with Rell Nightwind in Stormwind Keep, then take the flight to Admiral Rogers on the Skyfire. Complete the Garrosh'ar landing, Paw'don rescue and Twinspire Keep quests. The route includes parallel errands so it does not send you to a locked later hand-in.\n\n2. Continue through the Vanguard wreck and Slingtail camp into Pearlfin Village. Complete the Pearlfin introductions and waterspeaking ceremony, then listen to the four SI:7 reports. Arm the Pearlfin Aqualytes and train the Adepts through A Perfect Match and Bigger Fish to Fry.\n\n3. Alliance: accept Let Them Burn from Instructor Sharpfin at Pearlfin Village, around 58.8,81.7. Defeat the fifteen required Grookin Reinforcements or Slingtail Recruits, return and choose/collect Fishy.\n\n4. Horde: start All Aboard! in Orgrimmar, depart on Hellscream's Fist and complete the Honeydew landing. Follow Zin'jun, Strongarm Airstrip and Lorewalker Cho's Circle of Bone / Circle of Stone story, then help the hozen at Grookin Hill.\n\n5. Horde: after Orders are Orders, Instant Messaging and Beyond the Horizon, accept What's in a Name Name? from Chief Kah Kah at 27.9,47.1. Defeat seven Riverstride Jinyu, return and collect Fishy. Learn the reward on either faction; it can also be traded as a cage.",
        reviewedAt = "2026-11-13",
        wowheadUrl = "https://www.wowhead.com/npc=62829",
        references = { "https://www.wowhead.com/npc=62829", "https://www.wowhead.com/item=84105" },
    },
    [849] = {
        category = "Professions",
        source = "Pandaria Inscription - trainer recipe",
        itemId = 89368,
        description = "A permanent kite companion made by a scribe. It cannot fight pet battles.",
        difficulty = "easy",
        difficultyReason = "An ordinary trainer craft or purchase from another player.",
        requirements = "Pandaria Inscription 75 to craft; no Inscription needed to learn the finished item",
        cost = "1 Light Parchment and 4 Ink of Dreams",
        tips = "The kites are companions in the Pet Journal, not mount kites. Clear the 'Can Battle' filter when checking ownership. Both colours are separate species.",
        waypoints = {
