        petNPCID = 66104,
        name = "Chi-Ji Kite",
        sourceType = "Professions",
        stepCount = 4,
        acquisition = "Difficulty: Easy - An ordinary trainer craft or purchase from another player.\n\n1. Buy the finished Chi-Ji Kite from another player if you do not want to level Inscription. For self-crafting, learn Pandaria Inscription and raise that expansion's skill to 75; old 600-skill comments refer to the former combined profession bar.\n\n2. Visit Lorewalker Huynh at the Seat of Knowledge above Mogu'shan Palace, Vale 81.9,29.3, and learn the Chi-Ji Kite recipe. Fly up to the balcony; entering the Mogu'shan Palace dungeon does not reach this trainer. Use Zidormi if the assault phase obscures the building.\n\n3. Gather 1 Light Parchment and 4 Ink of Dreams. Craft Chi-Ji Kite with a Virtuoso Inking Set, then use the pet-teaching item from your bags.\n\n4. Find the kite in your Pet Journal with non-battling companions visible. You can summon it as a companion, but it cannot fill a combat slot.",
        reviewedAt = "2026-11-13",
        wowheadUrl = "https://www.wowhead.com/npc=66104",
    },
