    [851] = {
        category = "Pet Battles",
        source = "Wild capture - north-western Uldum lake shore",
        description = "Capture Horned Lizard in a pet battle. The map marks a search area; ordinary non-battle critters cannot be trapped.",
        difficulty = "easy",
        difficultyReason = "An ordinary wild capture once you have a team strong enough for this area's pets.",
        requirements = "Battle Pet Training, an unlocked trap, and pets suitable for the local battle level",
        cost = "No purchase; wild captures cannot be bought as cages",
        tips = "Track Pets on the minimap. A green paw identifies a battle pet. Catching any quality is enough to add the species; a battle-stone can improve quality later.",
        commentIDs = { 1737980, 1731028, 1746425 },
        waypoints = {
            {
                mapID = 249,
                x = 0.306,
                y = 0.15,
                step = 2,
                label = "north-western Uldum lake shore - Horned Lizard search area",
            },
            { mapID = 249, x = 0.56, y = 0.35100000000000003, step = 2, label = "Zidormi - earlier Uldum" },
        },
        petNPCID = 62894,
        name = "Horned Lizard",
        sourceType = "Pet Battles",
        stepCount = 4,
        acquisition = "Difficulty: Easy - An ordinary wild capture once you have a team strong enough for this area's pets.\n\n1. Open the Pet Journal and prepare a healthy team. Bring a pet near the target's level or Terrible Turnip with Weakening Blow so a critical hit does not kill the pet you want to trap.\n\n2. Travel to north-western Uldum lake shore (30.6,15.0). Use the earlier Uldum through Zidormi if you are in the assault phase, then search the lake edge. The old Badlands and Silithus journal listings were misleading. These can come in linked groups; inspect the actual species name.\n\n3. Start a pet battle and inspect all enemy slots for Horned Lizard. Check the species name, not just its model. If it appears as a backline pet, defeat the enemies ahead of it before lowering its health.\n\n4. Lower Horned Lizard below 35% health, then use Trap until the capture succeeds. Finish the rest of the enemy team and win the battle to keep it. Heal before the next attempt if necessary; only one enemy can be captured per battle.",
        reviewedAt = "2026-11-13",
        wowheadUrl = "https://www.wowhead.com/npc=62894",
        references = { "https://www.wowhead.com/npc=62894" },
    },
    [855] = {
        category = "Achievements",
        source = "Collect 400 different companion pets",
        itemId = 89736,
        sourceAchievementId = 7501,
        description = "An account-wide species-collection milestone. Duplicate copies do not increase the unique-pet count.",
        difficulty = "medium",
        difficultyReason = "A broad collection target; inexpensive vendors and ordinary captures make steady progress.",
        requirements = "400 different eligible pet species",
        cost = "Varies with collecting methods; no reward purchase",
        tips = "Check achievement 7501 for progress. Collecting three copies or multiple breeds of one species is still one species. Use the Auction House's uncollected filter to avoid buying duplicates.",
        waypoints = {
            {
                mapID = 125,
                x = 0.586,
                y = 0.396,
                step = 2,
                label = "Breanni - optional inexpensive species for the collection milestone",
            },
        },
        petNPCID = 66491,
        name = "Venus",
        sourceType = "Achievements",
        stepCount = 4,
        acquisition = "Difficulty: Medium - A broad collection target; inexpensive vendors and ordinary captures make steady progress.\n\n1. Open the achievement tracker for 400 unique companion pets and the Pet Journal's uncollected filter. Build the collection using vendor pets, wild captures and tradeable raid pets; your character's level is not a count of collected species.\n\n2. Start with inexpensive vendor species: Breanni in Northrend Dalaran 58.6,39.6 and the racial pet vendors in your capitals. Learn each new species immediately. Compare your owned count before buying another colour that may be the same species.\n\n3. Use wild pet battles to collect missing species zone by zone. The newly listed Pandaria wild pets provide many additions without rare raid drops. For bought cages check that your account can learn their pet level.\n\n4. Continue until the achievement's unique count reaches 400. Claim/learn the Venus reward when delivered, checking the Pet Journal and mailbox. There is no separate reputation or quest turn-in after the milestone.",
        reviewedAt = "2026-11-13",
        wowheadUrl = "https://www.wowhead.com/npc=66491",
        references = { "https://www.wowhead.com/npc=66491", "https://www.wowhead.com/item=89736" },
    },
    [856] = {
        category = "Achievements",
        source = "Time to Open a Pet Store - 400 pet-battle achievement points",
        itemId = 89686,
        sourceAchievementId = 7521,
        description = "Awarded for pet-battle achievement points, not for owning four hundred pets.",
        difficulty = "hard",
        difficultyReason = "A broad set of capture, battle, training and tamer achievements is required.",
        requirements = "400 points from achievements in the Pet Battles category",
        cost = "No reward purchase",
        tips = "Only Pet Battles achievement points count. Account achievement points from raids, quests or guild categories do not help this counter. The launch-era total-point limits in old comments are obsolete; many later achievements can contribute.",
        waypoints = {
            {
                mapID = 84,
                x = 0.6940000000000001,
                y = 0.244,
                step = 3,
                label = "Audrey Burnhep - optional Alliance tamer-quest route",
            },
            { mapID = 85, x = 0.526, y = 0.593, step = 3, label = "Varzok - optional Horde tamer-quest route" },
        },
        commentIDs = { 1726642 },
        petNPCID = 66450,
        name = "Jade Tentacle",
        sourceType = "Achievements",
        stepCount = 4,
        acquisition = "Difficulty: Hard - A broad set of capture, battle, training and tamer achievements is required.\n\n1. Track Time to Open a Pet Store (achievement 7521) and open the Pet Battles achievement category. Read the remaining point total there; the number of pets in the journal is a different counter.\n\n2. Collect low-cost points from ordinary actions: win consecutive wild battles, capture pets from different families and zones, catch rare-quality pets, and level pets from each family. Finish regional Safari lists using still-obtainable species rather than chasing retired promotional rewards.\n\n3. Complete your faction's tamer quest progression through Pandaria and its spirit battles. The live quest routes on the spirit pets identify the next unfinished tamer. Add the Raiding with Leashes pet collections for further pet-category achievement points.\n\n4. Continue with obtainable later-expansion pet achievements until the tracked category total reaches 400. Claim or learn Jade Tentacle when awarded. There is no Jade Forest tentacle NPC or currency vendor to visit for the final reward.",
        reviewedAt = "2026-11-13",
        wowheadUrl = "https://www.wowhead.com/npc=66450",
        references = { "https://www.wowhead.com/npc=66450", "https://www.wowhead.com/item=89686" },
    },
    [1042] = {
        category = "Reputation",
        source = "Sho - Best Friend friendship",
        itemId = 85222,
        description = "Sho mails the pet at Best Friend; The Tillers Exalted on its own does not award it.",
        difficulty = "medium",
        difficultyReason = "Build one farmer's friendship through gifts, food and available errands.",
        requirements = "Best Friend with Sho on the character earning the mail",
        cost = "Friendship gifts / food",
        tips = "Sho's favourite gift is Lovely Apple. The individual farmer bar is separate from The Tillers faction reputation. Reputation tokens for The Tillers do not automatically finish Sho friendship.",
        waypoints = {
            { mapID = 376, x = 0.29600000000000004, y = 0.306, step = 1, label = "Sho - Heartland home" },
            { mapID = 376, x = 0.45, y = 0.45, step = 2, label = "Heartland fields - Dark Soil gift search area" },
            { mapID = 376, x = 0.53, y = 0.518, step = 1, label = "Halfhill Market - Sho when visiting" },
        },
        commentIDs = { 1694525, 1693848 },
        petNPCID = 63370,
        name = "Red Cricket",
        sourceType = "Reputation",
        stepCount = 4,
        acquisition = "Difficulty: Medium - Build one farmer's friendship through gifts, food and available errands.\n\n1. Find Sho in the Heartland around 29.6,30.6, Valley of the Four Winds, or at Halfhill when she is that day's visitor. Complete Farmer Yoon's farm introduction if you have not opened the Tillers activities yet.\n\n2. Search Dark Soil around the Heartland fields and loot farmer gifts. Give Lovely Apples to Sho for her preferred gift reward; other accepted gifts work more slowly. These repeatable gift deliveries can advance friendship without waiting for a fixed sequence of story quests.\n\n3. When offered, complete Sho's errands and her favourite-food daily. Her food is Eternal Blossom Fish; bring five portions for the daily delivery rather than expecting an ordinary fish catch to count as the cooked dish.\n\n4. Reach Best Friend with Sho, then check that character's mailbox for the Chirping Package / Red Cricket reward. Open the package and use the pet. Red Cricket cannot currently be caged; old comments about buying another player's cricket predate that restriction.",
        reviewedAt = "2026-11-13",
        wowheadUrl = "https://www.wowhead.com/npc=63370",
        references = { "https://www.wowhead.com/npc=63370", "https://www.wowhead.com/item=85222" },
    },
