        petNPCID = 62999,
        name = "Temple Snake",
        sourceType = "Pet Battles",
        stepCount = 4,
        acquisition = "Difficulty: Easy - An ordinary wild capture once you have a team strong enough for this area's pets.\n\n1. Open the Pet Journal and prepare a healthy team. Bring a pet near the target's level or Terrible Turnip with Weakening Blow so a critical hit does not kill the pet you want to trap.\n\n2. Travel to the outdoor Jade Temple Grounds (52.0,56.8). Walk the temple grounds for primary snakes and inspect backline slots in other Jade Forest battles. Exalted collectors can also find it behind the Arboretum hatchlings, but that reputation is not required for the outdoor snake.\n\n3. Start a pet battle and inspect all enemy slots for Temple Snake. Check the species name, not just its model. If it appears as a backline pet, defeat the enemies ahead of it before lowering its health.\n\n4. Lower Temple Snake below 35% health, then use Trap until the capture succeeds. Finish the rest of the enemy team and win the battle to keep it. Heal before the next attempt if necessary; only one enemy can be captured per battle.",
        reviewedAt = "2026-11-13",
        wowheadUrl = "https://www.wowhead.com/npc=62999",
        references = { "https://www.wowhead.com/npc=62999" },
