--[====[
Preserved inactive research: Data/Expansions/MistsOfPandaria/PetQuestRoutes.lua
This material is retained for reference and does not register character quest routes.

-- Retail quest objectives and the complete faction-specific Fishy stories.
-- Hand-authored instructions; pickup/prerequisite facts reuse the existing
-- Retail source index. Active Blizzard objective waypoints take precedence.
local _,TDP=...
local routes=TDP.CollectionQuestRoutes
local guides=TDP.CollectionWalkthroughs.pets
local sources=TDP.CollectionSourceIndex.quests
local function point(map,x,y) return {mapID=map,x=x/100,y=y/100} end
local function quest(id,name,instructions,options)
    local s=sources[id] or {}
    local q={questID=id,name=name,instructions=instructions,sourceURL="https://www.wowhead.com/quest="..id,
        requires=s.sourceQuests or {},requiredCount=s.sqreq,faction=s.faction,races=s.races,classes=s.classes,
        npcID=s.qgs and s.qgs[1],turnInReference=true,objectiveReference=true}
    local p=s.coords and s.coords[1]
    if p then q.pickup=point(p[1],p[2],p[3]) end
    for k,v in pairs(options or {}) do q[k]=v end
    return q
end
local function define(key,name,quests,options)
    local route=options or {}
    route.key,route.name,route.quests,route.version=key,name,quests,1
    route.reviewedAt="2026-11-13"
    routes[key]=route
    return route
end
local function attach(ids,route,optional)
    for _,id in ipairs(ids) do
        local guide=guides[id]
        if guide then
            guide.questRoutes=guide.questRoutes or {}
            guide.questRoutes[#guide.questRoutes+1]=route
            guide.keepReferencePins=true
            if optional then guide.questRoutesOptional=true end
        end
    end
end
local function copy(value)
    if type(value)~="table" then return value end
    local result={}
    for k,v in pairs(value) do result[k]=copy(v) end
    return result
end

local fishyAlliance={
    quest(29548,"The Mission","Speak with Rell Nightwind in Stormwind Keep at 78.9,39.7, then take the offered Skyfire transport to the Pandaria assault. Enable trivial-quest tracking; do not sail directly to Pearlfin and expect its final quest to be available.",{requires={},pickup=point(84,78.9,39.7)}),
    quest(31732,"Unleash Hell","On the Skyfire speak to the assault crew and use the gunship weapons to destroy sixty Garrosh'ar troops, eight shredders and two warships. Remain in the introduction phase until all objectives are credited."),
    quest(31733,"Touching Ground","Use the offered parachute/landing interaction on the Skyfire and report to the Alliance beachhead. Simply flying down from an unrelated phase does not replace the landing credit."),
    quest(30069,"No Plan Survives Contact","At the southern beachhead kill the required Garrosh'ar Grunts and Gear-Greasers. Accept Welcome Wagons as well and complete both before advancing to the barricade."),
    quest(31734,"Welcome Wagons","Destroy five Garrosh'ar Supply Wagons around the landing beach and return to the Alliance assault group."),
    quest(31735,"The Right Tool For The Job","Use the quest-provided Skyfire equipment to breach the barricades and confront Ga'trul. Finish both barricade and confrontation objectives before following the assault inland."),
    quest(31736,"Envoy of the Alliance","Speak with the pandaren envoy at the occupied village and complete the conversation. Collect The Cost of War in the same hub."),
    quest(31737,"The Cost of War","Defeat ten Sha Haunts and five Sha Harbingers around the village. Clear the released sha and finish the envoy task before moving to the next camp."),
    quest(29552,"Critical Condition","Find and rescue six injured Skyfire pilots around the wreckage. Use the quest's rescue interaction on the marked pilots rather than killing nearby enemies."),
    quest(31738,"Pillaging Peons","Kill twelve Garrosh'ar Peons in the wreckage area. Complete this alongside Critical Condition and the cider errand."),
    quest(31739,"Priorities!","Collect six barrels of Applebloom Cider from the wreckage and follow the hand-in to the next encounter."),
    quest(31740,"Koukou's Rampage","Defeat Koukou and complete the rescue scene. Return to the assault camp; the wounded pilots and peons must also be finished before the Twinspire tasks open."),
    quest(31741,"Twinspire Keep","Kill fifteen Garrosh'ar defenders at Twinspire Keep. Pick up the named-target, bombing and cub-rescue tasks before clearing the keep."),
    quest(31742,"Fractured Forces","Find and defeat both Dalgan and Bellandra inside the keep area. Ordinary defenders do not replace either named-target credit."),
    quest(31743,"Smoke Before Fire","Use the supplied explosives on all four indicated keep targets. Follow each objective's marker and confirm all four are checked."),
    quest(31744,"Unfair Trade","Free eight Pandaren cubs at Twinspire Keep. Use their rescue interactions; avoid finishing the assault with prisoners still uncaught."),
    quest(30070,"The Fall of Ga'trul","After all four keep errands are handed in, confront and defeat Ga'trul and remain through the sha scene."),
    quest(31745,"Onward and Inward","Report to the next Alliance party beyond the keep. This is the transition into the missing-admiral and Pearlfin story; it is not the Fishy reward yet."),
    quest(29555,"The White Pawn","Inspect the wreckage for the clues and the captain's log requested by the quest. Accept the nearby hozen-clearing quest at the same time."),
    quest(29556,"Hozen Aren't Your Friends, Hozen Are Your Enemies","Defeat ten Slingtail hozen around the wreck. Hand this in together with The White Pawn."),
    quest(29553,"The Missing Admiral","Follow the clue trail and speak to the indicated Pearlfin contact. Complete the handoff to Elder Lusshan rather than searching the whole coast for the admiral."),
    quest(29558,"The Path of War","Kill twelve Slingtail hozen at the encampment. Accept Freeing Our Brothers and Ancient Power at the same hub before leaving."),
    quest(29559,"Freeing Our Brothers","Release six Pearlfin prisoners in the Slingtail camp using the rescue interaction. Finish the surrounding hozen and skull objectives on the same trip."),
    quest(29560,"Ancient Power","Collect eight Ancient Jinyu Skulls in the Slingtail area and return all three camp errands to the Pearlfin quest giver."),
    quest(29759,"Kung Din","Defeat Kung Din at the quest-marked camp and loot the key needed to release the captives."),
    quest(29562,"Jailbreak","Use the key to free ten Pearlfin Fishrippers, then return to Pearlfin Village. Opening only one cage does not necessarily complete the required prisoner count."),
    quest(29883,"The Pearlfin Situation","Speak with all four Pearlfin leaders indicated in the village. Pick up Road Rations while making the circuit."),
    quest(29885,"Road Rations","Collect six Tortoise Flanks from the local tortoises. Turn this and the four-leader introduction in before expecting the next Pearlfin tasks."),
    quest(29762,"Family Heirlooms","Recover eight heirlooms from the fallen Pearlfin while working on The Elders' Instruments. Check each body/loot marker rather than killing unrelated wildlife."),
    quest(29887,"The Elders' Instruments","Recover all four named ceremonial instruments for Elder Lusshan. Each is a separate objective; return once both this and Family Heirlooms are complete."),
    quest(29894,"Spirits of the Water","Join Elder Lusshan's water ceremony and remain for its complete vision/conversation credit."),
    quest(29733,"SI:7 Report: Lost in the Woods","Speak with Rell at Pearlfin Village and begin the first playable SI:7 report. Follow its scenario instructions until the report finishes."),
    quest(29725,"SI:7 Report: Fire From the Sky","Speak to the reporting agent and play Sully's account. Scout the three marked shrines using the supplied actions, then return to the present-day report."),
    quest(29726,"SI:7 Report: Hostile Natives","Play Little Lu's report, visit the three required statues and finish the Widow encounter. Complete the report's own objectives before exiting its phase."),
    quest(29727,"SI:7 Report: Take No Prisoners","Play the final report and guide Sully through the escape/rescue sequence. Stay through the ending to unlock the Pearlfin training quests."),
    quest(29903,"A Perfect Match","Use the supplied Alliance equipment to arm nine Pearlfin Aqualytes. This is an interaction/training task, not a request to kill the friendly jinyu."),
    quest(29904,"Bigger Fish to Fry","Lead the trainees against twenty-four required wildlife targets. Keep the quest's training group active and confirm the kill counter before returning."),
    quest(29905,"Let Them Burn","Lead the trained Pearlfin against fifteen required hozen reinforcements/recruits and finish the assault. Turn the quest in at Pearlfin Village and choose/claim Fishy, then learn the pet item."),
}
attach({847},define("mop-fishy-alliance","Fishy - Alliance landing and Pearlfin story",fishyAlliance,{
    faction="Alliance",endQuestID=29905,completionPin=point(371,58.8,81.7),completionText="Pearlfin story complete - claim and learn Fishy",
    after="These are this character's quest flags. A purchased Fishy cage bypasses the story; it does not complete these quests. Optional board breadcrumbs are omitted because Rell can begin The Mission directly.",
}),true)

