    quest(31853,"All Aboard!","Speak with General Nazgrim in Grommash Hold, Orgrimmar 48.6,70.8. Follow the offered transport to the gunship off Durotar, rather than travelling straight to the completed Pandaria village phase.",{requires={},pickup=point(85,48.6,70.8)}),
    quest(29690,"Into the Mists","Report to Nazgrim aboard the Horde gunship off Durotar at 61.2,44.6 and take the Pandaria introduction. Finish the arrival scene."),
    quest(31765,"Paint it Red!","Use the gunship's assault equipment to destroy eighty Alliance troops and nine cannons. Complete both counters before leaving the vehicle."),
    quest(31766,"Touching Ground","Use the offered rope/rappel interaction to descend and report to the landing force. Stay in the Horde introduction phase."),
    quest(31767,"Finish Them!","Defeat fifteen Alliance troops at the landing site. Pick up Fire Is Always the Answer before clearing the same area."),
    quest(31768,"Fire Is Always the Answer","Burn ten Alliance Munitions Stockpiles with the supplied quest tool. Hand in both beach tasks to continue."),
    quest(31769,"The Final Blow!","Use the assault interaction to breach the barricades and confront Captain Doren. Finish the scene before looking for the Honeydew village tasks."),
    quest(29694,"Regroup!","Find all four separated Horde companions around Honeydew Village. Speak with each marked survivor and confirm all four credits."),
    quest(31770,"You're Either With Us Or...","Speak with the pandaren mayor and finish the village allegiance conversation. Collect the sha and prowler tasks in the same hub."),
    quest(31771,"Face to Face With Consequence","Defeat twenty Sha Haunts and seven Sha Harbingers released around the village."),
    quest(31773,"Prowler Problems","Kill ten Sha-Infested Prowlers and hand in the village errands. All four regroup/village tasks are required for the Zinjun handoff."),
    quest(31774,"Seeking Zin'jun","Report to Zin'jun at the marked northern Jade Forest camp. Do not skip the preceding village hand-ins."),
    quest(29765,"Cryin' My Eyes Out","Recover all four of Zin'jun's belongings from the surrounding hozen area and return them to him."),
    quest(29804,"Seein' Red","Confront and defeat Konk, then follow the Horde force to the airstrip assault camp."),
    quest(31775,"Assault on the Airstrip","Defeat fifteen Alliance defenders at the airstrip. Accept all four assault errands before clearing it."),
    quest(31776,"Strongarm Tactics","Defeat the four named Alliance targets shown by the quest. Regular airstrip troops do not count as those leaders."),
    quest(31777,"Choppertunity","Use the supplied rocket equipment to destroy twelve Alliance Gyrocopters. Aim at the quest-marked aircraft rather than wasting rockets on ground troops."),
    quest(31778,"Unreliable Allies","Rally twelve hozen volunteers through the quest interaction and complete the other airstrip tasks before advancing."),
    quest(31779,"The Darkness Within","Confront Captain Doren after the airstrip objectives are handed in. Defeat the encounter and wait for its ending credit."),
    quest(31999,"Nazgrim's Command","Read the command object at the next Horde camp around 27.5,24.2 and report to the assigned companions. This object-started handoff opens the Grookin preparation quests."),
    quest(29815,"Forensic Science","Collect eight Paint-Speckled Chlorophyll from the local plant creatures and bring the samples to the Horde camp. Take Missed Me By... at the same hub."),
    quest(29821,"Missed Me By... That Much!","Recover the requested crate at Serenity Falls. Follow the crate marker; killing enemies at the falls alone does not give the delivery item."),
    quest(29827,"Acid Rain","Use the quest gyrocopter and its bombing action to defeat twenty-five targets of each required enemy group. Land and hand in after both counters are complete."),
    quest(29822,"Lay of the Land","Take the scouting trip with Dook Ookem and inspect both marked shrines. Finish the landing/conversation sequence to reach Lorewalker Cho."),
    quest(31121,"Stay a While, and Listen","Join Lorewalker Cho at the teapot near 27.5,32.6. Use the tea/story interaction and remain until the conversation completes."),
    quest(31132,"A Mile in My Shoes","Accompany Cho to the Circle of Bone and follow the lesson's interactions. Do not simply fly to the destination and leave him behind."),
    quest(31134,"If These Stones Could Speak","Read all three marked monoliths at the Circle of Bone and return to Cho."),
    quest(31152,"Peering Into the Past","Follow Cho through the Circle of Stone sequence and complete the vision/escort before leaving."),
    quest(31167,"Family Tree","Return to Cho's family shrine and use the incense/ceremony interaction. Wait for the full story credit."),
    quest(29879,"Swallowed Whole","Recover five hozen and five trout from the marked river creatures. Loot the required enemies and hand in both counts."),
    quest(29935,"Orders are Orders","Recover the Alliance Orders in the quest area and deliver them to the Horde contact. Follow the document marker rather than continuing with unrelated Jade Forest side quests."),
    quest(29936,"Instant Messaging","Use the supplied signal flare at the indicated location to summon/contact the next Horde party."),
    quest(29941,"Beyond the Horizon","Speak with all four named members of the Horde party. Complete every conversation before expecting the jinyu-clearing task."),
    quest(31239,"What's in a Name Name?","Defeat seven required jinyu at the quest-marked location and return to Chief Kah Kah. Claim Fishy from the quest reward and use the pet item."),
}
