    {31915,31897,"Grand Master Lydia Accoste","Grand Master Trixxy",{42,40.2,76.6,"Lydia Accoste"},{83,65.6,64.4,"Stone Cold Trixxy"},
        "Alliance: defeat Lydia's Undead/Magic team near Karazhan using Critter/Dragonkin attacks. Horde: defeat Trixxy's mixed team in Winterspring. Accept the one-time grand-master quest at the trainer, win and turn it in there."},
