        "Defeat Aki in the earlier Vale: Chirrup the Critter, Stormlash the Dragonkin and Whiskers the Aquatic. Use Beast, Humanoid and Flying damage respectively, and avoid wasting your large hit into an avoidance effect. Use Zidormi's earlier Vale if needed, then hand in Grand Master Aki."},
}
local tamerRoutes={}
for sideIndex,side in ipairs({"Alliance","Horde"}) do
    local capital=sideIndex==1 and point(84,69.4,24.4) or point(85,52.6,59.3)
    local trainer=sideIndex==1 and "Audrey Burnhep" or "Varzok"
    local qs,pins={},{}
    local previous
    local function append(id,name,text,pickup,objective,options)
        local opts={requires=previous and {previous} or {},pickup=pickup,turnIn=objective or pickup,turnInReference=false,
            objective=objective,objectiveReference=false,faction=side}
        for k,v in pairs(options or {}) do opts[k]=v end
        qs[#qs+1]=quest(id,name,text,opts)
        previous=id
        return #qs
    end
    for _,lesson in ipairs(lessons) do
        local id=lesson[sideIndex]
        local alternatives={}
        for _,other in ipairs(lesson[5]) do if other~=id then alternatives[#alternatives+1]=other end end
        append(id,lesson[3],lesson[4].." Return to "..trainer..".",capital,capital,{altQuests=alternatives})
    end
    local early=sideIndex==1 and earlyAlliance or earlyHorde
    local pickup=capital
    for _,s in ipairs(early) do
        local target=point(s[3],s[4],s[5])
        local step=append(s[1],s[2],s[7].." Accept the next trainer handoff after winning.",pickup,target)
        pins[#pins+1]=TDP.PandariaPetGuides.pin(s[3],s[4],s[5],step,s[6].." - early tamer battle")
        pickup=target
    end
    append(sideIndex==1 and 31917 or 31918,"A Tamer's Homecoming","Return from the last local trainer to "..trainer.." in your capital and hand in the homecoming. This opens the continent-wide five-tamer assignment.",pickup,capital)
    for chapterIndex,chapter in ipairs(chapters) do
        local targets=sideIndex==2 and chapter[5] or chapter[4]
        targets=targets or chapter[4]
        local name=chapter[3]=="home" and (sideIndex==1 and "Eastern Kingdoms" or "Kalimdor") or chapter[3]
        local destinations={}
        for _,s in ipairs(targets) do destinations[#destinations+1]=s[4].." ("..s[2]..","..s[3]..")" end
        local step=append(chapter[sideIndex],"Battle Pet Tamers: "..name,chapter[6].." Locations: "..table.concat(destinations,"; ")..". Complete all checked quest objectives, then use the quest's remote completion if offered. Accept the grand-master quest at that grand master; it is not a capital hand-in.",capital,nil,{turnInReference=true})
        for _,s in ipairs(targets) do pins[#pins+1]=TDP.PandariaPetGuides.pin(s[1],s[2],s[3],step,s[4].." - "..name.." assignment") end
        local grand=grandMasters[chapterIndex]
        local target=sideIndex==2 and grand[6] or grand[5]
        target=target or grand[5]
        local p=point(target[1],target[2],target[3])
        local gstep=append(grand[sideIndex],grand[2+sideIndex],grand[7],p,p)
        pins[#pins+1]=TDP.PandariaPetGuides.pin(target[1],target[2],target[3],gstep,target[4].." - grand master")
        if chapterIndex<5 then
            local returns=({{31976,31977,"The Returning Champion"},{31981,31982,"Exceeding Expectations"},{31984,31983,"A Brief Reprieve"},{31985,31986,"The Triumphant Return"}})[chapterIndex]
            append(returns[sideIndex],returns[3],"Accept the return quest from "..target[4]..", travel back to "..trainer.." and turn it in. Take the next continent assignment before leaving the capital.",p,capital,
                chapterIndex==1 and {altQuests={sideIndex==1 and 31975 or 31980}} or nil)
        end
    end
    local route=define("mop-pet-tamers-"..side:lower(),side.." pet training through Grand Master Aki",qs,{
        faction=side,accountWide=true,endQuestID=31951,completionPin=point(390,31.2,74.2),completionText="Grand Master Aki complete - Pandaria challenge introductions unlocked",
        after="The tamer story is an account unlock. Wild captures and ordinary character quest chains use their own rules. A developed level-25 roster is still needed for the Pandaria challenge battles.",
    })
    tamerRoutes[side]=route
    -- Porcupette's early grand master is sufficient; do not require Aki for it.
    local porcupette=copy(route)
    while #porcupette.quests>13 do table.remove(porcupette.quests) end
    porcupette.key,porcupette.name="mop-porcupette-tamers-"..side:lower(),side.." first grand-master supply bags"
    porcupette.endQuestID=sideIndex==1 and 31915 or 31897
    porcupette.completionPin=sideIndex==1 and point(42,40.2,76.6) or point(83,65.6,64.4)
    porcupette.completionText="First grand master unlocked - repeat the daily for supply bags"
    porcupette.after="The first faction grand master's daily bag can contain Porcupette. Grand Master Aki is not a prerequisite for this early bag route; buying a cage bypasses the tamer unlocks."
    routes[porcupette.key]=porcupette
    attach({381},porcupette,true)
    for _,id in ipairs({868,1124,1125,1126,1176,1196,1197,1198}) do
        local guide=guides[id]
        if guide then for _,p in ipairs(pins) do guide.waypoints[#guide.waypoints+1]=copy(p) end end
    end
end
for _,side in ipairs({"Alliance","Horde"}) do
    local shrine=side=="Alliance" and point(390,86.6,60.2) or point(390,60.8,23.6)
    for _,pet in ipairs({
        {868,32439,422,61.2,87.4,"Flowing Pandaren Spirit"},
        {1124,32434,388,57.0,42.2,"Burning Pandaren Spirit"},
        {1125,32440,371,28.8,36.0,"Whispering Pandaren Spirit"},
        {1126,32441,379,64.8,93.6,"Thundering Pandaren Spirit"},
    }) do
        local qs=copy(tamerRoutes[side].quests)
        qs[#qs+1]=quest(32428,"Pandaren Spirit Tamer","At your faction's shrine accept the introduction, defeat all four spirits in any order using this pet's numbered guide, then return to choose one guaranteed spirit pet. The initial choice unlocks the four separate daily bags.",{
            requires={31951},faction=side,pickup=shrine,turnIn=shrine,turnInReference=false,
        })
        attach({pet[1]},define("mop-pet-spirit-"..pet[1].."-"..side:lower(),side.." spirit introduction and matching daily",qs,{
            faction=side,accountWide=true,endQuestID=32428,repeatableRewards=true,
            repeatableQuests={quest(pet[2],pet[6],"Accept the daily from this spirit, defeat its team, return and open its matching supply bag. Other spirits' bags do not contain this species.",{
                requires={},daily=true,pickup=point(pet[3],pet[4],pet[5]),turnIn=point(pet[3],pet[4],pet[5]),turnInReference=false,
            })},completionPin=point(pet[3],pet[4],pet[5]),completionText="Initial choice complete - matching spirit daily bag remains a random source",
        }),true)
    end
    local qs=copy(tamerRoutes[side].quests)
    qs[#qs+1]=quest(32603,"Beasts of Fable","Accept the initial quest at the shrine. Defeat all ten legendary pets using the guide's three regional circuits, then return for Red Panda and the daily-book unlock. These are battles, not captures.",{
        requires={31951},faction=side,pickup=shrine,turnIn=shrine,turnInReference=false,
    })
    local beasts=define("mop-pet-fables-"..side:lower(),side.." Beasts of Fable introduction",qs,{
        faction=side,accountWide=true,endQuestID=32603,completionPin=shrine,completionText="Initial ten-beast quest complete - learn Red Panda; the other pandas come from daily bags",
    })
    attach({1176,1196,1197,1198},beasts,true)
end

-- Current Brawler introduction; a previous invitation can bypass this route.
for _,side in ipairs({"Alliance","Horde"}) do
    local alliance=side=="Alliance"
    local first,second,last=alliance and 92845 or 92715,alliance and 92851 or 92740,alliance and 94363 or 94372
    local start=alliance and point(2339,51.0,43.6) or point(2339,51.4,40.0)
    local seller=alliance and point(499,54.6,61.6) or point(85,73.6,31.6)
    local arena=alliance and point(499,52.2,46.3) or point(85,70.1,31.5)
    attach({1142},define("mop-clockem-entry-"..side:lower(),side.." current Brawler's Guild entry",{
        quest(first,"By Invitation Only?","Speak to "..(alliance and "the Babbling Brawler" or "the Garrulous Gladiator").." in Dornogal, then report to "..(alliance and "Pick Butterworth in Bizmo's Brawlpub, reached through Stormwind's Deeprun Tram" or "Alton Philips outside Brawl'gar Arena in Orgrimmar")..". A current invitation can skip this introduction.",{
            requires={},faction=side,pickup=start,turnIn=seller,turnInReference=false}),
        quest(second,"Questionable Qualifications","Pay the seller 50 gold for the current Brawler's Guild invitation and complete the invitation interaction. Follow the quest's instruction to use the invitation before reporting inside.",{
            requires={first},faction=side,pickup=seller,turnIn=seller,turnInReference=false}),
        quest(last,"The Gloves Are Off","Speak with your faction's arena Bouncer / Grunt and finish the entry handoff. Queue for ranked Brawls, earn Rank 3 and buy Clock'em for 500 gold before discounts.",{
